import { useState } from 'react';
import { Link } from 'react-router-dom';
import { mediaArticlesList } from '../../mocks/mediaArticles';
import ArticleCard from './components/ArticleCard';
import PopularArticlesSidebar from './components/PopularArticlesSidebar';
import GlobalHeader from '../../components/feature/GlobalHeader';
import GlobalFooter from '../../components/feature/GlobalFooter';
import Breadcrumb from '../../components/feature/Breadcrumb';

export default function MediaPage() {
  const [activeCategory, setActiveCategory] = useState('全て');
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState('date');

  const categories = ['全て', '新車', 'パーツ', 'メンテナンス', 'ニュース'];

  // フィルタリング
  let filteredArticles = mediaArticlesList.filter((article) => {
    const matchCategory = activeCategory === '全て' || article.category === activeCategory;
    const matchSearch =
      searchQuery === '' ||
      article.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      article.excerpt.toLowerCase().includes(searchQuery.toLowerCase());
    return matchCategory && matchSearch;
  });

  // ソート
  if (sortBy === 'date') {
    filteredArticles = [...filteredArticles].sort((a, b) => b.id - a.id);
  } else if (sortBy === 'views') {
    filteredArticles = [...filteredArticles].sort((a, b) => b.views - a.views);
  }

  return (
    <div className="min-h-screen bg-white">
      {/* 共通ヘッダー */}
      <GlobalHeader />

      {/* パンくずリスト */}
      <Breadcrumb items={[{ label: 'メディア総合' }]} />

      {/* メインコンテンツ */}
      <div className="max-w-[1400px] mx-auto py-8 px-6">
        <div className="flex items-center justify-between mb-6">
          <h1 className="text-3xl font-bold text-gray-800 flex items-center gap-3">
            <i className="ri-newspaper-line text-blue-600"></i>
            メディア総合
          </h1>
        </div>

        {/* 検索バー */}
        <div className="bg-white border border-gray-200 rounded-lg p-4 mb-6">
          <div className="flex gap-3">
            <div className="flex-1 flex">
              <input
                type="text"
                placeholder="記事を検索..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="flex-1 border border-gray-300 px-4 py-2 text-sm rounded-l focus:outline-none focus:border-blue-500 cursor-text"
              />
              <button className="bg-blue-600 text-white px-6 py-2 rounded-r font-bold hover:bg-blue-700 whitespace-nowrap cursor-pointer">
                <i className="ri-search-line"></i>
              </button>
            </div>
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
              className="border border-gray-300 px-4 py-2 text-sm rounded cursor-pointer focus:outline-none focus:border-blue-500"
            >
              <option value="date">新着順</option>
              <option value="views">閲覧数順</option>
            </select>
          </div>
        </div>

        {/* カテゴリタブ */}
        <div className="flex gap-2 mb-6 flex-wrap">
          {categories.map((category) => (
            <button
              key={category}
              onClick={() => setActiveCategory(category)}
              className={`px-6 py-3 rounded-lg font-bold text-sm whitespace-nowrap cursor-pointer ${
                activeCategory === category
                  ? 'bg-blue-600 text-white'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {category}
            </button>
          ))}
        </div>

        {/* コンテンツエリア */}
        <div className="flex gap-6">
          {/* 記事一覧 */}
          <div className="flex-1">
            <div className="mb-4 text-sm text-gray-600">
              {filteredArticles.length}件の記事
            </div>
            <div className="grid grid-cols-3 gap-6">
              {filteredArticles.map((article) => (
                <ArticleCard key={article.id} article={article} />
              ))}
            </div>
            {filteredArticles.length === 0 && (
              <div className="text-center py-12">
                <i className="ri-file-search-line text-6xl text-gray-300 mb-4"></i>
                <p className="text-gray-500">該当する記事が見つかりませんでした</p>
              </div>
            )}
          </div>

          {/* サイドバー */}
          <div className="w-80 flex-shrink-0">
            <PopularArticlesSidebar />
          </div>
        </div>
      </div>

      {/* フッター */}
      <GlobalFooter />
    </div>
  );
}